<?php $flt = []; foreach (['q' => 'common.search', 'from' => 'common.from', 'to' => 'common.to'] as $k => $l) if ($f[$k] !== '') $flt[] = t($l) . ': ' . $f[$k];
if ($f['type']) $flt[] = t('incident.type') . ': ' . enum_label('event', $f['type']); if ($f['status']) $flt[] = t('incident.status') . ': ' . enum_label('incident_status', $f['status']);
if ($f['category']) $flt[] = t('incident.category') . ': ' . \App\Support\Ref::name('category', $f['category']); if ($f['department']) $flt[] = t('incident.department') . ': ' . \App\Support\Ref::name('department', $f['department']);
if ($f['branch']) $flt[] = t('incident.branch') . ': ' . \App\Support\Ref::name('branch', $f['branch']); ?>
<p class="print-meta"><?= e(t('report.filters')) ?>: <?= $flt ? e(implode(' · ', $flt)) : e(t('common.all')) ?> — <?= e(t('report.rows', ['shown' => count($rows), 'total' => $total])) ?></p>
<?php if ($total > count($rows)): ?><div class="msg info noprint"><?= e(t('report.truncated', ['n' => count($rows)])) ?></div><?php endif; ?>
<table class="data"><thead><tr><th><?= e(t('incident.id')) ?></th><th><?= e(t('incident.type')) ?></th><th><?= e(t('incident.name')) ?></th><th><?= e(t('incident.occurrence_date')) ?></th><th><?= e(t('incident.category')) ?></th><th><?= e(t('incident.department')) ?></th>
  <th class="num"><?= e(t('incident.gross_loss')) ?></th><th class="num"><?= e(t('incident.recoveries')) ?></th><th class="num"><?= e(t('incident.net_loss')) ?></th><th><?= e(t('incident.status')) ?></th></tr></thead><tbody>
<?php foreach ($rows as $r): ?><tr><td class="nowrap"><?= e($r['incident_code']) ?></td><td><?= e(enum_label('event', $r['event_type'])) ?></td><td><?= e($r['title']) ?></td><td class="nowrap"><?= e($r['occurrence_date']) ?></td><td><?= e(lname($r, 'cat')) ?></td><td><?= e(lname($r, 'dept')) ?><?= $r['branch_id'] ? ' / ' . e(lname($r, 'branch')) : '' ?></td>
  <td class="num"><?= e(money($r['gross_loss'])) ?></td><td class="num"><?= e(money($r['recoveries'])) ?></td><td class="num"><?= e(money($r['net_loss'])) ?></td><td><?= e(enum_label('incident_status', $r['status'])) ?></td></tr><?php endforeach; ?>
</tbody><tfoot><tr><td colspan="6"><?= e(t('incident.totals_filtered', ['n' => $sums['count']])) ?></td><td class="num"><?= e(money(\App\Core\Money::toDb($sums['gross']))) ?></td><td class="num"><?= e(money(\App\Core\Money::toDb($sums['recoveries']))) ?></td><td class="num"><?= e(money(\App\Core\Money::toDb($sums['net']))) ?></td><td></td></tr></tfoot></table>
